definition.script:
pipeline {
    agent any

    environment {
        // Define environment variables to store credentials and repo info
        GIT_CREDENTIALS = credentials('git-cred')
        GIT_REPO_URL = 'github.com/NOUR-BEN-ALI/MyApp-PFE.git' 
        GIT_BRANCH = 'tempo'
        REPO_DIR = 'MyApp-PFE'
        registry = "docker.io" 
        registryCredential = 'docker_visionaryops' 
    }

    stages {
        stage('Clone my Branch from Git') {
            steps {
                script {
                    if (fileExists(REPO_DIR)) {
                        dir(REPO_DIR) {
                            sh 'git pull'
                        }
                    } else {
                        sh "git clone --branch ${env.GIT_BRANCH} https://NOUR-BEN-ALI:${env.GIT_CREDENTIALS}@${env.GIT_REPO_URL} ${REPO_DIR}"
                    }
                }
            }
        }
        stage('Clean and compile with Maven ms1') {
            steps {
                dir(REPO_DIR +'/Microservice1') {
                    sh 'mvn clean install -DskipTests'
                }
            }
        }
        stage('Clean and compile with Maven ms2') {
            steps {
                dir(REPO_DIR +'/Microservice2') {
                    sh 'mvn clean install -DskipTests'
                }
            }
        }
        stage('Clean and compile with Maven ms3') {
            steps {
                dir(REPO_DIR +'/Microservice3') {
                    sh 'mvn clean install -DskipTests'
                }
            }
        }

stage('Building  image ms1') { 

            steps { 
dir(REPO_DIR +'/Microservice1'){
                script { 

                    dockerImage = docker.build registry + ":$BUILD_NUMBER" 

                }
}

            } 

        }



        stage('Building  image ms2') { 

            steps { 
dir(REPO_DIR +'/Microservice2'){
                script { 

                    dockerImage = docker.build registry + ":$BUILD_NUMBER" 

                }
}

            } 

        }


        stage('Building  image ms3') { 

            steps { 
dir(REPO_DIR +'/Microservice3'){
                script { 

                    dockerImage = docker.build registry + ":$BUILD_NUMBER" 

                }
}

            } 

        }

    }
}
